"use client";

/**
 * Per-kind channel matrix; the digest column is hidden unless `digest_email`
 * is on.
 *
 * Must call (do not reimplement): isEnabled
 */
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useFormAction } from "@/hooks/use-form-action";
import { isEnabled } from "@/lib/feature-flags";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { ActionResult } from "@/types/api";
import type { OrgId, UserId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";
import type { ReactElement } from "react";

export type NotificationPreferencesFormProps = {
  orgId: OrgId;
  userId: UserId;
  preferences: readonly NotificationPreference[];
  flags: FeatureFlagSnapshot;
  onSubmit: (
    input: UpdateNotificationPreferenceInput,
  ) => Promise<ActionResult<NotificationPreference>>;
};

const KIND_LABELS: Readonly<Record<NotificationKind, string>> = {
  issue_assigned: "Issue assigned to me",
  issue_status_changed: "Issue status changed",
  issue_due_soon: "Issue due soon",
  issue_overdue: "Issue overdue",
  comment_created: "New comment",
  comment_mention: "I was mentioned",
  member_invited: "Member invited",
  member_joined: "Member joined",
  project_archived: "Project archived",
  plan_limit_reached: "Plan limit reached",
  digest_ready: "Daily digest ready",
};

export function NotificationPreferencesForm(
  props: NotificationPreferencesFormProps,
): ReactElement | null {
  const { orgId, userId, preferences, flags, onSubmit } = props;
  const { submit, pending } = useFormAction(onSubmit);

  const digestOn =
    flags.digest_email === true ||
    isEnabled("digest_email", ANONYMOUS_FLAG_CONTEXT);

  function update(
    preference: NotificationPreference,
    patch: Partial<
      Pick<NotificationPreference, "inApp" | "email" | "digestOnly">
    >,
  ): void {
    void submit({
      orgId,
      userId,
      kind: preference.kind,
      inApp: patch.inApp ?? preference.inApp,
      email: patch.email ?? preference.email,
      digestOnly: patch.digestOnly ?? preference.digestOnly,
    });
  }

  return (
    <Table caption="Notification preferences">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Event</TableHeaderCell>
          <TableHeaderCell>In app</TableHeaderCell>
          <TableHeaderCell>Email</TableHeaderCell>
          {digestOn ? <TableHeaderCell>Digest only</TableHeaderCell> : null}
        </TableRow>
      </TableHead>

      <TableBody>
        {preferences.map((preference) => (
          <TableRow key={preference.kind}>
            <TableCell>{KIND_LABELS[preference.kind]}</TableCell>

            <TableCell className="w-24">
              <Switch
                name={`${preference.kind}-in-app`}
                checked={preference.inApp}
                disabled={pending}
                onChange={(checked) => update(preference, { inApp: checked })}
              />
            </TableCell>

            <TableCell className="w-24">
              <Switch
                name={`${preference.kind}-email`}
                checked={preference.email}
                disabled={pending}
                onChange={(checked) => update(preference, { email: checked })}
              />
            </TableCell>

            {digestOn ? (
              <TableCell className="w-28">
                <Switch
                  name={`${preference.kind}-digest`}
                  checked={preference.digestOnly}
                  // Batching only makes sense when email is on at all.
                  disabled={pending || !preference.email}
                  onChange={(checked) =>
                    update(preference, { digestOnly: checked })
                  }
                />
              </TableCell>
            ) : null}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}

