/**
 * Ownership offers. The partial unique index is the database's guarantee that
 * a workspace never has two open offers; lapsed offers are moved out of
 * `pending` before a new one is inserted.
 */
export const ownershipHandovers = sqliteTable(
  "ownership_handovers",
  {
    id: idColumn(),
    ...tenantColumns,
    fromUserId: text("from_user_id").notNull(),
    toUserId: text("to_user_id").notNull(),
    status: text("status", {
      enum: ["pending", "accepted", "declined", "canceled", "expired"],
    })
      .notNull()
      .default("pending"),
    expiresAt: text("expires_at").notNull(),
    resolvedAt: text("resolved_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("ownership_handovers_open_idx")
      .on(table.orgId)
      .where(sql`${table.status} = 'pending'`),
    index("ownership_handovers_org_status_idx").on(table.orgId, table.status),
  ],
);

export type OrganizationRow = typeof organizations.$inferSelect;
export type NewOrganizationRow = typeof organizations.$inferInsert;
export type OrganizationUsageRow = typeof organizationUsage.$inferSelect;
export type OwnershipHandoverRow = typeof ownershipHandovers.$inferSelect;

