/**
 * Workspace ownership offers. Every query is filtered by `orgId`.
 *
 * Rows are never deleted. "Open" means `status = 'pending'` and not yet past
 * `expires_at`; a pending row past its window is lapsed and is moved to
 * `expired` by `expireLapsedHandovers()` before a new offer is written.
 */
import { and, eq, gt, lte, or, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { OwnershipHandover } from "@/types/organization";

export interface NewOwnershipHandover {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly createdAt: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}

/** The single `pending` row for the org, lapsed or not; callers judge the window. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function insertHandover(
  input: NewOwnershipHandover,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      resolvedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();
  return toOwnershipHandover(row);
}

/**
 * Retires every pending offer whose window has closed. Its `resolvedAt` is the
 * instant it lapsed, not the instant it was noticed.
 */
export async function expireLapsedHandovers(
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({
      status: "expired",
      resolvedAt: sql`${ownershipHandovers.expiresAt}`,
      updatedAt: at,
    })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        lte(ownershipHandovers.expiresAt, at),
      ),
    )
    .run();
}

/**
 * Moves a pending offer to a terminal status. Returns `null` when the offer is
 * no longer pending, so two concurrent resolutions cannot both succeed.
 */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: "accepted" | "declined" | "canceled",
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Withdraws every open offer that names the user on either side. Lapsed offers
 * are left alone: they were never open, so there is nothing to withdraw.
 */
export async function cancelOpenHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .returning()
    .all();
  return rows.length;
}

