/**
 * The recorded owner offers the workspace to another active member. Only one
 * offer may be open at a time; the offered member alone is notified.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const org = await requireRecordedOwner(actor, orgId);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }
  await requireActiveMember(orgId, toUserId);

  const now = new Date();
  // A lapsed offer is retired first, so it neither blocks this one nor stays "pending".
  await ownershipRepo.expireLapsedHandovers(orgId, toIsoTimestamp(now));
  if (await ownershipRepo.findPendingHandover(orgId)) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const offer = await ownershipRepo.insertHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + OWNERSHIP_OFFER_TTL_MS)),
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership offered to you",
    body: `${org.name} can be handed over to you until ${offer.expiresAt}`,
    href: "/settings/danger",
    actorId: actor.userId,
  });

  return offer;
}

/**
 * The offered member takes over. The incoming member is promoted before the
 * outgoing owner is demoted, so the workspace always has an owner and the
 * last-owner rule in member-service never has to refuse the change.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await requireOfferedToActor(actor, orgId, now);
  const incoming = await requireActiveMember(orgId, actor.userId);

  // Claimed before any role moves: a concurrent accept loses here, not halfway through.
  const claimed = await ownershipRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(now),
  );
  if (!claimed) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  const outgoing = await memberRepo.findMember(orgId, offer.fromUserId);
  if (outgoing?.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: outgoing.role,
      to: demoted.role,
    });
  }

  const org = await orgRepo.setOrgOwner(orgId, actor.userId);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: offer.fromUserId,
    toUserId: actor.userId,
  });

  return org;
}

/** The offered member turns the offer down; the owner may offer again afterwards. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await requireOfferedToActor(actor, orgId, now);

  const declined = await ownershipRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(now),
  );
  if (!declined) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return declined;
}

/** The recorded owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  await requireRecordedOwner(actor, orgId);

  const now = new Date();
  const open = await findOpenHandover(orgId, now);
  if (!open) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const canceled = await ownershipRepo.resolveHandover(
    orgId,
    open.id,
    "canceled",
    toIsoTimestamp(now),
  );
  if (!canceled) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return canceled;
}

/** The open offer for the workspace, or `null`. Any member may read it. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return findOpenHandover(orgId, new Date());
}

/**
 * The guard offer and withdrawal share: the actor must hold the owner role and
 * be the recorded owner. Holding the role alone is not enough.
 */
async function requireRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:transfer_ownership", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:transfer_ownership", {
      allowed: false,
      action: "org:transfer_ownership",
      resourceKind: "organization",
      reason: "denied_by_ownership",
    });
  }
  return org;
}

/** The pending offer the actor was made. Anyone else, and any lapsed offer, is refused. */
async function requireOfferedToActor(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await ownershipRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending, now)) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

/** The open offer, if any. A lapsed offer is not open, even while still marked pending. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await ownershipRepo.findPendingHandover(orgId);
  return pending && !isLapsed(pending, now) ? pending : null;
}

/** An offer is lapsed from the instant its window closes, inclusive. */
function isLapsed(offer: OwnershipHandover, now: Date): boolean {
  return Date.parse(offer.expiresAt) <= now.getTime();
}

/** Offers go only to active members; a removed or unknown user is simply not found. */
async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

