/**
 * Workspace ownership handover: offers, acceptance, refusals, lapse and the
 * cascade when either side leaves the workspace.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError } from "@/lib/errors";
import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import { NotFoundError } from "@/server/services/_support";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { IsoTimestamp, MemberId, OrgId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;
const START = new Date("2026-10-01T09:00:00.000Z");
const NO_SUCH_USER = "01HZZZZZZZZZZZZZZZZZZZZZZZ" as UserId;

let cleanup: () => void;
let detachAudit: Unsubscribe;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** The actor as the database sees the member now, not as the fixture first wrote them. */
async function actorFor(orgId: OrgId, userId: UserId): Promise<Actor> {
  const actor = await memberService.resolveActor(userId, orgId);
  if (!actor) throw new Error("fixture member is not active");
  return actor;
}

async function memberIdOf(orgId: OrgId, userId: UserId): Promise<MemberId> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member) throw new Error("fixture member missing");
  return member.id;
}

async function roleOf(orgId: OrgId, userId: UserId): Promise<string | undefined> {
  return (await memberRepo.findMember(orgId, userId))?.role;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachAudit = registerActivityListeners();
});

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(START);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

describe("initiateOwnershipHandover", () => {
  it("opens one pending offer that lapses exactly seven days after it was made", async () => {
    const tenant = await createTenant("offer-open");
    const orgId = tenant.org.id;

    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.admin,
    );

    expect(offer).toMatchObject({
      orgId,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.admin,
      status: "pending",
      resolvedAt: null,
    });
    expect(offer.createdAt).toBe(START.toISOString());
    expect(Date.parse(offer.expiresAt)).toBe(START.getTime() + 7 * DAY_MS);
  });

  it("shows the open offer to every member and alerts only the offered member", async () => {
    const tenant = await createTenant("offer-visible");
    const orgId = tenant.org.id;
    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.admin,
    );

    for (const role of ["viewer", "member", "admin", "owner"] as const) {
      const pending = await organizationService.getPendingOwnershipHandover(
        tenant.actors[role],
        orgId,
      );
      expect(pending?.id, role).toBe(offer.id);
    }

    const query = {
      orgId,
      unreadOnly: false,
      kind: ["ownership_handover"] as const,
      limit: 25,
      cursor: null,
    };
    const alerted = await notificationService.listNotifications(tenant.actors.owner, {
      ...query,
      recipientId: tenant.userIds.admin,
    });
    const bystander = await notificationService.listNotifications(tenant.actors.owner, {
      ...query,
      recipientId: tenant.userIds.member,
    });
    expect(alerted.items).toHaveLength(1);
    expect(bystander.items).toHaveLength(0);
  });

  it("refuses a second offer while one is open", async () => {
    const tenant = await createTenant("offer-second");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);

    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.member),
    ).rejects.toMatchObject({ reason: "pending_exists" });
    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.member),
    ).rejects.toBeInstanceOf(OwnershipHandoverError);
  });

  it("refuses a member who holds the owner role but is not the recorded owner", async () => {
    const tenant = await createTenant("offer-second-owner");
    const orgId = tenant.org.id;
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.admin),
      role: "owner",
    });

    await expect(
      organizationService.initiateOwnershipHandover(
        await actorFor(orgId, tenant.userIds.admin),
        orgId,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an offer to the owner themselves, a removed member, an unknown user and another workspace's member", async () => {
    const tenant = await createTenant("offer-targets");
    const other = await createTenant("offer-targets-other");
    const orgId = tenant.org.id;

    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.owner),
    ).rejects.toMatchObject({ reason: "self" });

    await memberService.removeMember(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.viewer),
    });
    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, NO_SUCH_USER),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, other.userIds.admin),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a non-owner and an actor from another workspace", async () => {
    const tenant = await createTenant("offer-roles");
    const other = await createTenant("offer-roles-other");
    const orgId = tenant.org.id;

    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.admin, orgId, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      organizationService.initiateOwnershipHandover(other.actors.owner, orgId, tenant.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("acceptOwnershipHandover", () => {
  it("makes the offered member the owner and steps the previous owner down to admin", async () => {
    const tenant = await createTenant("accept-handover");
    const orgId = tenant.org.id;
    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.viewer);

    const org = await organizationService.acceptOwnershipHandover(
      await actorFor(orgId, tenant.userIds.viewer),
      orgId,
    );

    expect(org.ownerId).toBe(tenant.userIds.viewer);
    expect(await roleOf(orgId, tenant.userIds.viewer)).toBe("owner");
    expect(await roleOf(orgId, tenant.userIds.owner)).toBe("admin");
    expect(roleChanges.map(({ from, to, actorId }) => ({ from, to, actorId }))).toEqual([
      { from: "viewer", to: "owner", actorId: tenant.userIds.viewer },
      { from: "owner", to: "admin", actorId: tenant.userIds.viewer },
    ]);
    expect(transfers).toEqual([
      {
        orgId,
        actorId: tenant.userIds.viewer,
        occurredAt: expect.any(String),
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.viewer,
      },
    ]);
    expect(await organizationService.getPendingOwnershipHandover(tenant.actors.owner, orgId)).toBeNull();

    const audit = await activityService.listActivity(await actorFor(orgId, tenant.userIds.viewer), {
      orgId,
      action: ["organization.ownership_transferred"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: tenant.userIds.viewer,
      subjectKind: "organization",
      subjectId: orgId,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.viewer },
    });
  });

  it("only changes the previous owner's role when the offered member already owns", async () => {
    const tenant = await createTenant("accept-existing-owner");
    const orgId = tenant.org.id;
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.admin),
      role: "owner",
    });
    const roleChanges = capture("member.role_changed");
    await organizationService.initiateOwnershipHandover(
      await actorFor(orgId, tenant.userIds.owner),
      orgId,
      tenant.userIds.admin,
    );

    const org = await organizationService.acceptOwnershipHandover(
      await actorFor(orgId, tenant.userIds.admin),
      orgId,
    );

    expect(org.ownerId).toBe(tenant.userIds.admin);
    expect(await roleOf(orgId, tenant.userIds.admin)).toBe("owner");
    expect(await roleOf(orgId, tenant.userIds.owner)).toBe("admin");
    expect(roleChanges).toHaveLength(2);
    expect(roleChanges[1]).toMatchObject({ from: "owner", to: "admin" });
  });

  it("leaves the previous owner's role alone if they no longer hold it", async () => {
    const tenant = await createTenant("accept-demoted-owner");
    const orgId = tenant.org.id;
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.admin),
      role: "owner",
    });
    await organizationService.initiateOwnershipHandover(
      await actorFor(orgId, tenant.userIds.owner),
      orgId,
      tenant.userIds.member,
    );
    // The other owner steps the recorded owner down while the offer is open.
    await memberService.updateMemberRole(await actorFor(orgId, tenant.userIds.admin), {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.owner),
      role: "member",
    });
    const roleChanges = capture("member.role_changed");

    await organizationService.acceptOwnershipHandover(await actorFor(orgId, tenant.userIds.member), orgId);

    expect(await roleOf(orgId, tenant.userIds.owner)).toBe("member");
    expect(await roleOf(orgId, tenant.userIds.member)).toBe("owner");
    expect(roleChanges.map(({ from, to }) => ({ from, to }))).toEqual([
      { from: "member", to: "owner" },
    ]);
  });

  it("can be acted on once: a second acceptance is refused", async () => {
    const tenant = await createTenant("accept-twice");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);
    await organizationService.acceptOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId);

    await expect(
      organizationService.acceptOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
  });

  it("hands over the alerts and billing, and lets the new owner remove the old one", async () => {
    const tenant = await createTenant("accept-followups");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.viewer);
    await organizationService.acceptOwnershipHandover(await actorFor(orgId, tenant.userIds.viewer), orgId);

    await expect(
      billingService.changePlan(await actorFor(orgId, tenant.userIds.owner), {
        orgId,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await billingService.changePlan(await actorFor(orgId, tenant.userIds.viewer), {
      orgId,
      plan: "enterprise",
      interval: "monthly",
    });

    await emit("member.joined", {
      orgId,
      actorId: null,
      occurredAt: START.toISOString() as IsoTimestamp,
      memberId: await memberIdOf(orgId, tenant.userIds.member),
      userId: tenant.userIds.member,
      role: "member",
    });
    const joinQuery = { orgId, unreadOnly: false, kind: ["member_joined"] as const, limit: 25, cursor: null };
    const newOwnerAlerts = await notificationService.listNotifications(
      await actorFor(orgId, tenant.userIds.viewer),
      { ...joinQuery, recipientId: tenant.userIds.viewer },
    );
    const oldOwnerAlerts = await notificationService.listNotifications(
      await actorFor(orgId, tenant.userIds.viewer),
      { ...joinQuery, recipientId: tenant.userIds.owner },
    );
    expect(newOwnerAlerts.items).toHaveLength(1);
    expect(oldOwnerAlerts.items).toHaveLength(0);

    await memberService.removeMember(await actorFor(orgId, tenant.userIds.viewer), {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.owner),
    });
    expect(await memberRepo.findMember(orgId, tenant.userIds.owner)).toBeNull();
  });

  it("refuses an acceptance from a member who was not offered the workspace", async () => {
    const tenant = await createTenant("accept-wrong-person");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);

    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.member, orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    expect(await roleOf(orgId, tenant.userIds.owner)).toBe("owner");
  });
});

describe("declining and withdrawing", () => {
  it("lets the offered member decline, after which the owner may offer again", async () => {
    const tenant = await createTenant("decline-offer");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);

    const declined = await organizationService.declineOwnershipHandover(
      await actorFor(orgId, tenant.userIds.admin),
      orgId,
    );

    expect(declined).toMatchObject({ status: "declined", resolvedAt: START.toISOString() });
    expect(await organizationService.getPendingOwnershipHandover(tenant.actors.owner, orgId)).toBeNull();
    await expect(
      organizationService.declineOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    const next = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    expect(next.status).toBe("pending");
  });

  it("lets the recorded owner withdraw an open offer, and refuses a second withdrawal", async () => {
    const tenant = await createTenant("withdraw-offer");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);

    const canceled = await organizationService.cancelOwnershipHandover(tenant.actors.owner, orgId);

    expect(canceled).toMatchObject({ status: "canceled", resolvedAt: START.toISOString() });
    expect(await organizationService.getPendingOwnershipHandover(tenant.actors.owner, orgId)).toBeNull();
    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(
      organizationService.declineOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
  });

  it("refuses withdrawal by a second owner who is not the recorded owner", async () => {
    const tenant = await createTenant("withdraw-second-owner");
    const orgId = tenant.org.id;
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.admin),
      role: "owner",
    });
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.member);

    await expect(
      organizationService.cancelOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await organizationService.getPendingOwnershipHandover(tenant.actors.owner, orgId))?.status).toBe(
      "pending",
    );
  });
});

describe("the seven-day window", () => {
  it("can still be accepted one millisecond before the seventh day ends", async () => {
    const tenant = await createTenant("window-open");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);
    vi.setSystemTime(START.getTime() + 7 * DAY_MS - 1);

    const org = await organizationService.acceptOwnershipHandover(
      await actorFor(orgId, tenant.userIds.admin),
      orgId,
    );

    expect(org.ownerId).toBe(tenant.userIds.admin);
  });

  it("is expired from the seventh day on, changes nothing, and no longer blocks a new offer", async () => {
    const tenant = await createTenant("window-lapsed");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);
    vi.setSystemTime(START.getTime() + 7 * DAY_MS);

    expect(await organizationService.getPendingOwnershipHandover(tenant.actors.owner, orgId)).toBeNull();
    await expect(
      organizationService.acceptOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      organizationService.declineOwnershipHandover(await actorFor(orgId, tenant.userIds.admin), orgId),
    ).rejects.toMatchObject({ reason: "expired" });
    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.member, orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    expect(await roleOf(orgId, tenant.userIds.admin)).toBe("admin");
    expect((await memberService.resolveActor(tenant.userIds.owner, orgId))?.role).toBe("owner");

    const next = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    expect(next).toMatchObject({ toUserId: tenant.userIds.member, status: "pending" });
    expect(Date.parse(next.expiresAt)).toBe(START.getTime() + 14 * DAY_MS);
  });
});

describe("removal withdraws an open offer", () => {
  it("when the offered member is removed", async () => {
    const tenant = await createTenant("remove-offered");
    const orgId = tenant.org.id;
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin);

    await memberService.removeMember(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.admin),
    });

    expect(await organizationService.getPendingOwnershipHandover(tenant.actors.owner, orgId)).toBeNull();
  });

  it("when the offering owner is removed while another owner remains", async () => {
    const tenant = await createTenant("remove-offering-owner");
    const orgId = tenant.org.id;
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.admin),
      role: "owner",
    });
    await organizationService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.member);

    await memberService.removeMember(await actorFor(orgId, tenant.userIds.admin), {
      orgId,
      memberId: await memberIdOf(orgId, tenant.userIds.owner),
    });

    expect(await organizationService.getPendingOwnershipHandover(tenant.actors.admin, orgId)).toBeNull();
  });
});

describe("workspace isolation", () => {
  it("keeps an offer invisible from another workspace and refuses every operation across the boundary", async () => {
    const home = await createTenant("isolation-home");
    const away = await createTenant("isolation-away");
    await organizationService.initiateOwnershipHandover(home.actors.owner, home.org.id, home.userIds.admin);

    expect(await organizationService.getPendingOwnershipHandover(away.actors.owner, away.org.id)).toBeNull();
    await expect(
      organizationService.getPendingOwnershipHandover(away.actors.owner, home.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.acceptOwnershipHandover(home.actors.admin, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.declineOwnershipHandover(home.actors.admin, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.cancelOwnershipHandover(home.actors.owner, away.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

